(()=>{const panel=document.getElementById('computer-info-panel'),page=document.getElementById('club-map-page'),close=document.getElementById('computer-info-close'),fields={name:document.getElementById('computer-info-name'),zone:document.getElementById('computer-info-zone'),status:document.getElementById('computer-info-status'),connection:document.getElementById('computer-info-connection'),lastSeen:document.getElementById('computer-info-last-seen'),session:document.getElementById('computer-session-info'),sessionState:document.getElementById('computer-info-session-state'),sessionEnd:document.getElementById('computer-info-session-end'),reservation:document.getElementById('computer-reservation-info'),staff:document.getElementById('computer-staff-info'),staffKind:document.getElementById('computer-info-staff-kind'),staffName:document.getElementById('computer-info-staff-name'),staffUntil:document.getElementById('computer-info-staff-until')};const staffKinds={pin:@json(__('Выход из агента по PIN-коду')),signin:@json(__('Сотрудник вошёл на ПК'))};const noData=@json(__('Нет данных')),labels={online:@json(__('Онлайн')),offline:@json(__('Офлайн')),available:@json(__('Доступен')),busy:@json(__('Занят')),service:@json(__('Сервис')),restarting:@json(__('Перезапуск')),reserved:@json(__('Забронирован')),idle:@json(__('Ожидает')),in_session:@json(__('В сессии')),locked:@json(__('Заблокирован')),shutting_down:@json(__('Выключается'))};const formatDate=value=>{if(!value)return noData;const date=new Date(value);return Number.isNaN(date.getTime())?noData:new Intl.DateTimeFormat(@json(app()->getLocale()),{dateStyle:'medium',timeStyle:'short'}).format(date)};const show=computer=>{const data=computer.dataset;fields.name.textContent=`${data.displayName} (#${data.number})`;fields.zone.textContent=data.zoneName||noData;fields.status.textContent=labels[data.status]||data.status||noData;fields.connection.textContent=labels[data.connection]||data.connection||noData;fields.lastSeen.textContent=formatDate(data.lastSeen);const hasSession=data.hasSession==='true'||data.agentState==='in_session';fields.session.hidden=!hasSession;if(hasSession){fields.sessionState.textContent=labels[data.agentState]||data.agentState||@json(__('В сессии'));fields.sessionEnd.textContent=formatDate(data.sessionEndsAt)}fields.staff.hidden=!data.staffUntil;if(data.staffUntil){fields.staffKind.textContent=staffKinds[data.staffKind]||noData;fields.staffName.textContent=data.staffName||@json(__('Не указан (общий PIN-код)'));fields.staffUntil.textContent=formatDate(data.staffUntil)}fields.reservation.hidden=data.isReserved!=='true';panel.hidden=false};document.querySelectorAll('.cm-computer').forEach(computer=>{computer.addEventListener('click',event=>{if(event.target.closest('.cm-computer-edit'))return;show(computer)});computer.addEventListener('pointerup',event=>{if(page.classList.contains('edit-mode')&&!event.target.closest('.cm-computer-edit'))show(computer)})});close.addEventListener('click',()=>{panel.hidden=true});})();
