<script>
(()=>{const open=document.getElementById('guest-session-open'),modal=document.getElementById('guest-session-modal'),form=document.getElementById('guest-session-form'),total=document.getElementById('guest-session-total'),error=document.getElementById('guest-session-error'),submit=document.getElementById('guest-session-submit'),csrf=@json(csrf_token()),endpoint=@json(route('club-computers.guest-session')),notice=document.getElementById('layout-status');
const selected=()=>Array.from(document.querySelectorAll('.cm-computer.selected'));
const money=new Intl.NumberFormat(@json(app()->getLocale()),{maximumFractionDigits:2});
const recalc=()=>{const computers=selected(),choice=form.elements.choice.value;let sum=0,missing=false;if(choice==='minutes'){const minutes=Number(form.elements.minutes.value)||0;computers.forEach(computer=>{const hour=Number(computer.dataset.zonePrice);if(!computer.dataset.zonePrice){missing=true;return}sum+=Math.floor((Math.round(hour*100)*minutes+30)/60)/100})}else{const price=Number(form.querySelector('input[name=choice]:checked')?.dataset.price)||0;sum=price*computers.length}
total.textContent=missing?@json(__('В зоне одного из ПК нет цены часа: поминутно не продать.')):@json(__('К оплате: :sum за :count ПК')).replace(':sum',money.format(sum)).replace(':count',computers.length)};
open?.addEventListener('click',()=>{if(!selected().length)return;error.textContent='';recalc();modal.classList.add('open')});
modal.querySelectorAll('[data-guest-close]').forEach(button=>button.addEventListener('click',()=>modal.classList.remove('open')));
form.addEventListener('input',recalc);
form.addEventListener('submit',async event=>{event.preventDefault();const computers=selected();if(!computers.length)return;const choice=form.elements.choice.value;const body={computer_ids:computers.map(item=>Number(item.dataset.id)),payment_method:form.elements.payment_method.value};if(choice==='minutes')body.minutes=Number(form.elements.minutes.value);else body.tariff_id=Number(choice.split(':')[1]);submit.disabled=true;error.textContent='';
try{const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,Accept:'application/json'},body:JSON.stringify(body)});const result=await response.json();if(!response.ok){error.textContent=Object.values(result.errors??{}).flat()[0]??result.message??@json(__('Не удалось подключить тариф.'));return}
modal.classList.remove('open');notice.textContent=result.message;notice.classList.add('show');window.setTimeout(()=>notice.classList.remove('show'),3000)}catch{error.textContent=@json(__('Нет связи с сервером. Повторите попытку.'))}finally{submit.disabled=false}})})();
</script>
@endpush
@endif
@endsection

