sList.remove('resizing','blocked');handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',end);save(card,{width,height})};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',end)})});
document.querySelectorAll('.cm-computer').forEach(computer=>computer.addEventListener('pointerdown',event=>{if(!page.classList.contains('edit-mode'))return;event.preventDefault();event.stopPropagation();const area=computer.parentElement,gridX=47,gridY=42,offset=5;computer.setPointerCapture(event.pointerId);computer.classList.add('moving');const startX=event.clientX,startY=event.clientY,left=parseInt(computer.style.left),top=parseInt(computer.style.top);const move=e=>{const limitX=Math.max(0,area.scrollWidth-computer.offsetWidth),limitY=Math.max(0,area.scrollHeight-computer.offsetHeight),maxX=limitX>=offset?offset+Math.floor((limitX-offset)/gridX)*gridX:0,maxY=limitY>=offset?offset+Math.floor((limitY-offset)/gridY)*gridY:0,snapX=offset+Math.round((left+e.clientX-startX-offset)/gridX)*gridX,snapY=offset+Math.round((top+e.clientY-startY-offset)/gridY)*gridY,nextX=Math.min(maxX,Math.max(offset,snapX)),nextY=Math.min(maxY,Math.max(offset,snapY)),occupied=Array.from(area.querySelectorAll('.cm-computer')).some(item=>item!==computer&&parseInt(item.style.left)===nextX&&parseInt(item.style.top)===nextY);computer.classList.toggle('blocked',occupied);if(!occupied){computer.style.left=nextX+'px';computer.style.top=nextY+'px'}};const end=async()=>{computer.classList.remove('moving','blocked');computer.removeEventListener('pointermove',move);computer.removeEventListener('pointerup',end);notice.classList.add('show');const response=await fetch(computer.dataset.saveUrl,{method:'PATCH',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:JSON.stringify({position_x:parseInt(computer.style.left),position_y:parseInt(computer.style.top)})});if(!response.ok){computer.style.left=left+'px';computer.style.top=top+'px'}notice.textContent=response.ok?@json(__('Место ПК сохранено')):@json(__('Ячейка занята'));setTimeout(()=>{notice.classList.remove('show');notice.textContent=@json(__('Сохраняем расположение…'))},1200)};computer.addEventListener('pointermove',move);computer.addEventListener('pointerup',end)}));@if($errors->any())toggle.checked=true;toggle.dispatchEvent(new Event('change'));open();@endif})();
(()=>{const page=document.getElementById('club-map-page'),panel=document.getElementById('computer-controls'),count=document.getElementById('selected-count'),buttons=document.querySelectorAll('[data-computer-action]'),csrf=@json(csrf_token()),endpoint=@json(route('club-computers.control'));const selected=()=>Array.from(document.querySelectorAll('.cm-computer.selected'));const refresh=()=>{const total=selected().length;count.textContent=total;panel.classList.toggle('show',total>0)};document.querySelectorAll('.cm-computer').forEach(computer=>computer.addEventListener('click',()=>{if(page.classList.contains('edit-mode'))return;computer.classList.toggle('selected');refresh()}));buttons.forEach(button=>button.addEventListener('click',async()=>{const computers=selected();if(!computers.length)return;buttons.forEach(item=>item.disabled=true);const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:JSON.stringify({computer_ids:computers.map(item=>Number(item.dataset.id)),action:button.dataset.computerAction})});if(response.ok){const result=await response.json();computers.forEach(computer=>{computer.classList.remove('available','online','offline','restarting');computer.classList.add(result.status)})}buttons.forEach(item=>item.disabled=false)}))})();
