@push('scripts')
<script>
(()=>{const button=document.getElementById('reserve-selected'),modal=document.getElementById('booking-modal'),form=document.getElementById('booking-form'),error=document.getElementById('booking-error'),summary=document.getElementById('booking-summary'),csrf=@json(csrf_token()),notice=document.getElementById('layout-status');
const selected=()=>Array.from(document.querySelectorAll('.cm-computer.selected'));
const show=text=>{notice.textContent=text;notice.classList.add('show');window.setTimeout(()=>notice.classList.remove('show'),2500)};
// Customer picker: club users by name or phone (as on the bookings page).
const search=document.getElementById('booking-customer'),userId=form.elements.user_id,list=document.getElementById('booking-customer-options');let timer=null,request=null;
const closeList=()=>{list.hidden=true;search.setAttribute('aria-expanded','false')};
search.addEventListener('input',()=>{userId.value='';clearTimeout(timer);timer=setTimeout(async()=>{const query=search.value.trim();if(query.length<2){closeList();return}request?.abort();request=new AbortController();try{const response=await fetch(@json(route('reservations.customers'))+'?'+new URLSearchParams({q:query}),{headers:{Accept:'application/json'},signal:request.signal});if(!response.ok)return;const customers=(await response.json()).data;list.replaceChildren(...(customers.length?customers.map(customer=>{const option=document.createElement('button');option.type='button';option.className='pos-user-option';option.dataset.id=customer.id;option.dataset.label=`${customer.name} · ${customer.phone??''}`;const name=document.createElement('strong');name.textContent=customer.name;const phone=document.createElement('small');phone.textContent=customer.phone??'';option.append(name,phone);return option}):[Object.assign(document.createElement('p'),{className:'pos-user-no-results',textContent:@json(__('Пользователь не найден'))})]));list.hidden=false;search.setAttribute('aria-expanded','true')}catch(e){if(e.name!=='AbortError')closeList()}},250)});
list.addEventListener('click',event=>{const option=event.target.closest('.pos-user-option');if(!option)return;userId.value=option.dataset.id;search.value=option.dataset.label;closeList()});
button.addEventListener('click',()=>{const computers=selected();if(!computers.length)return;error.textContent='';summary.textContent=@json(__('ПК: :list')).replace(':list',computers.map(computer=>computer.dataset.displayName).join(', '));document.getElementById('booking-flag-clear').hidden=!computers.some(computer=>computer.classList.contains('reserved'));modal.classList.add('open');search.focus()});
modal.querySelectorAll('[data-booking-close]').forEach(item=>item.addEventListener('click',()=>modal.classList.remove('open')));
form.addEventListener('submit',async event=>{event.preventDefault();if(!userId.value){error.textContent=@json(__('Выберите клиента из пользователей клуба.'));return}const submit=form.querySelector('[type=submit]');submit.disabled=true;error.textContent='';
try{const response=await fetch(@json(route('reservations.store-many')),{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,Accept:'application/json'},body:JSON.stringify({computer_ids:selected().map(computer=>Number(computer.dataset.id)),user_id:Number(userId.value),starts_at:form.elements.starts_at.value,duration_minutes:Number(form.elements.duration_minutes.value),note:form.elements.note.value||null})});const result=await response.json();if(!response.ok){error.textContent=Object.values(result.errors??{}).flat()[0]??result.message;return}
modal.classList.remove('open');show(result.message);window.setTimeout(()=>location.reload(),1200)}catch{error.textContent=@json(__('Нет связи с сервером. Повторите попытку.'))}finally{submit.disabled=false}});
// The old manual hold without a period: only to lift it from PCs that still have it.
document.getElementById('booking-flag-clear').addEventListener('click',async()=>{const computers=selected().filter(computer=>computer.classList.contains('reserved'));if(!computers.length)return;const response=await fetch(@json(route('club-computers.control')),{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,Accept:'application/json'},body:JSON.stringify({computer_ids:computers.map(computer=>Number(computer.dataset.id)),action:'reserve'})});if(response.ok){modal.classList.remove('open');show(@json(__('Бронь снята')));window.setTimeout(()=>location.reload(),800)}})})();
</script>
@endpush
